#!/usr/bin/env sh
# Regenerates mxm-ara's raw ARA bindings, src/sys/x86_64.rs and src/sys/aarch64.rs, from the
# vendored ARA_API 2.3 header (ara_api/ARAInterface.h, Apache-2.0, Celemony Software GmbH).
#
# Run it only when the vendored header changes; the generated files are checked in, so no build
# needs libclang. Needs bindgen-cli 0.73.2 (`cargo install bindgen-cli --version 0.73.2 --locked`)
# and libclang.
#
# Why two files: ARAInterface.h packs its structs with `#pragma pack(push, 1)` on x86 and
# `#pragma pack(push, 8)` on ARM, so the layouts differ by architecture (not by OS). It is read as
# C++17, where ARA's 32-bit enums have the fixed underlying type ARAInt32 on every platform.
set -eu

here=$(cd "$(dirname "$0")/.." && pwd)
bindgen=${BINDGEN:-bindgen}

for arch in x86_64 aarch64; do
    "$bindgen" "$here/ara_api/ARAInterface.h" \
        --allowlist-item '(k)?ARA.*' \
        --no-doc-comments \
        --disable-name-namespacing \
        --translate-enum-integer-types \
        --raw-line '// Generated by tools/gen-bindings.sh from ara_api/ARAInterface.h (ARA SDK 2.3); do not edit.' \
        -o "$here/src/sys/$arch.rs" \
        -- -x c++ -std=c++17 "--target=$arch-unknown-linux-gnu"
done
